25: static void mandel_simd_block(const float c_re[], const float c_im[], int count, int results[]) {
26:     float z_re[kSimdLanes];
27:     float z_im[kSimdLanes];
28:     int active[kSimdLanes];
29: 
30:     for (int lane = 0; lane < kSimdLanes; ++lane) {
31:         z_re[lane] = c_re[lane];
32:         z_im[lane] = c_im[lane];
33:         active[lane] = 1;
34:         results[lane] = 0;
35:     }
36: 
37:     for (int i = 0; i < count; ++i) {
38:         int any_active = 0;
39: #pragma omp simd reduction(|:any_active)
40:         for (int lane = 0; lane < kSimdLanes; ++lane) {
41:             if (active[lane]) {
42:                 if (z_re[lane] * z_re[lane] + z_im[lane] * z_im[lane] > 4.f) {
43:                     active[lane] = 0;
