46:                     float new_im = 2.f * z_re[lane] * z_im[lane];
47:                     z_re[lane] = c_re[lane] + new_re;
48:                     z_im[lane] = c_im[lane] + new_im;
49:                     results[lane] = i + 1;
50:                 }
51:             }
52:             any_active |= active[lane];
53:         }
54:         if (!any_active)
